import { test, expect } from '@playwright/test';

test.describe('Conflict Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/your-page-url');
  });

  test('should display conflict error message when saving a stale record', async ({ page }) => {
    // Simulate loading a stale record
    await page.fill(getByLabel('Record ID'), 'stale-record-id');
    await page.click(getByText('Load Record'));

    // Attempt to save the stale record
    await page.click(getByText('Save Record'));

    // Assert that the conflict error message is displayed
    const errorMessage = await page.getByRole('alert');
    await expect(errorMessage).toHaveText('Conflict: This record has been modified by another user.');
  });

  test('should not display conflict error message for valid save', async ({ page }) => {
    // Simulate loading a fresh record
    await page.fill(getByLabel('Record ID'), 'fresh-record-id');
    await page.click(getByText('Load Record'));

    // Attempt to save the fresh record
    await page.click(getByText('Save Record'));

    // Assert that no error message is displayed
    const errorMessage = await page.queryByRole('alert');
    await expect(errorMessage).toBeNull();
  });
});
